import{_ as n,o as a,c as t,ai as i}from"./chunks/framework.BxxKhjs3.js";const e="/pub-blog/assets/image-20240929004710826.DxJTEN2v.png",r="/pub-blog/assets/image-20240929010044597.CK82EWrP.png",p="/pub-blog/assets/image-20240929011503966.BAVR9uj6.png",l="/pub-blog/assets/image-20240929011553049.DslWGw4i.png",d="/pub-blog/assets/image-20240929011750736.BmEKU_y0.png",h="/pub-blog/assets/image-20240929012128049.BQqFQb6S.png",k="/pub-blog/assets/image-20240929012352082.BENiwJuk.png",o="/pub-blog/assets/PixPin_2024-09-29_01-31-34.CqzLduWC.gif",c="/pub-blog/assets/PixPin_2024-09-29_01-33-28.DqlaKwff.gif",g="/pub-blog/assets/image-20240929013703645.YemOisCO.png",E="/pub-blog/assets/image-20240929013924434.w32Fkxdd.png",m="/pub-blog/assets/image-20240929014127121.CI6s_-UU.png",u="/pub-blog/assets/image-20240929014309520.BJoUqVfx.png",b="/pub-blog/assets/image-20240929010933164.B8PYFOXF.png",y="/pub-blog/assets/image-20240929014948209.BnnOTW6Y.png",A="/pub-blog/assets/image-20240929015033130.C4I3xR9g.png",q=JSON.parse('{"title":"HarmonyOS Next 如何优雅的编写注释","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Next 如何优雅的编写注释/HarmonyNext如何优雅的编写注释.md","filePath":"鸿蒙开发技巧/HarmonyOS Next 如何优雅的编写注释/HarmonyNext如何优雅的编写注释.md","lastUpdated":1730788610000,"__rawMarkdown":"# HarmonyOS Next 如何优雅的编写注释\\n\\n# 程序员箴言\\n\\n**我最讨厌世界上的两种人：**\\n\\n1. **第一种是不写注释的人**\\n2. **第二种是让我写注释的人**\\n\\n# 前言\\n\\n随着HarmonyOS NEXT的发展加快，不少的公司已经陆续加大了资源来开发软件项目。那么伴随项目的发展，项目团队也需要按照一定\\n\\n的规范来编写项目注释或者代码的说明文档。\\n\\n我认为编写项目注释或者代码的说明文档最小的代价就是 直接通过**编写注释的方式**来实现代码的使用文档。\\n\\n目前主流的IDE都会支持 **jsDoc** 或者 **TypeDoc**。 我们按照规定的格式编写代码注释，便能获得以下好处：\\n\\n![image-20240929004710826](HarmonyNext%E5%A6%82%E4%BD%95%E4%BC%98%E9%9B%85%E7%9A%84%E7%BC%96%E5%86%99%E6%B3%A8%E9%87%8A.assets/image-20240929004710826.png)\\n\\n当我们想要调用 全局函数 **px2vp**时，提示工具会很清晰的给我展现出相关的使用说明。另外，如果是编写一个工具类库，还能基于相关工具生成好看的说明文档。\\n\\n> Person.ets\\n\\n```typescript\\n/**\\n * 一个工具人类\\n *\\n * @since 11\\n */\\nexport class Person {\\n  /**\\n   * 年龄\\n   */\\n  age: number = 18\\n\\n  /**\\n   *\\n   * 计算两个年龄相加的和\\n   * @param {number} n1 年龄1\\n   * @param {number} n2 年龄2\\n   * @returns {number} 总年龄\\n   */\\n  calcAge(n1: number, n2: number) {\\n    return n1 + n2\\n  }\\n}\\n```\\n\\n![image-20240929010044597](HarmonyNext%E5%A6%82%E4%BD%95%E4%BC%98%E9%9B%85%E7%9A%84%E7%BC%96%E5%86%99%E6%B3%A8%E9%87%8A.assets/image-20240929010044597.png)\\n\\n\\n\\n# DevEco Studio 自带的语法提示\\n\\njsDoc提供了对 常量、类、函数、接口、枚举等的修饰符，一般情况下不需要主动添加，因为  **DevEco Studio**  可以自动识别\\n\\n> @constant @class @function @interface @enmu 等\\n\\n**类**\\n\\n![image-20240929011503966](HarmonyNext%E5%A6%82%E4%BD%95%E4%BC%98%E9%9B%85%E7%9A%84%E7%BC%96%E5%86%99%E6%B3%A8%E9%87%8A.assets/image-20240929011503966.png)\\n\\n**枚举**\\n\\n![image-20240929011553049](HarmonyNext%E5%A6%82%E4%BD%95%E4%BC%98%E9%9B%85%E7%9A%84%E7%BC%96%E5%86%99%E6%B3%A8%E9%87%8A.assets/image-20240929011553049.png)\\n\\n\\n\\n并且，在你引入代码提示的时候，也可以直观的观察这里来判断它是什么类型\\n\\n![image-20240929011750736](HarmonyNext%E5%A6%82%E4%BD%95%E4%BC%98%E9%9B%85%E7%9A%84%E7%BC%96%E5%86%99%E6%B3%A8%E9%87%8A.assets/image-20240929011750736.png)\\n\\n\\n\\n---\\n\\n![image-20240929012128049](HarmonyNext%E5%A6%82%E4%BD%95%E4%BC%98%E9%9B%85%E7%9A%84%E7%BC%96%E5%86%99%E6%B3%A8%E9%87%8A.assets/image-20240929012128049.png)\\n\\n\\n\\n# 常见代码提示修饰符\\n\\n![image-20240929012352082](HarmonyNext%E5%A6%82%E4%BD%95%E4%BC%98%E9%9B%85%E7%9A%84%E7%BC%96%E5%86%99%E6%B3%A8%E9%87%8A.assets/image-20240929012352082.png)\\n\\n如图，如果我们想要实现**上图右侧**的一些语法提示功能，那么就需要自己编写合适的代码提示修饰符了\\n\\n通过编写一个类来演示，首先我们提供以下基本结构\\n\\n```typescript\\nexport class Person {\\n  age: number = 18\\n\\n  protected static async calcAge4(n1: number, n2: number) {\\n    return n1 + n2\\n  }\\n\\n  calcAge1(n1: number, n2: number) {\\n    return n1 + n2\\n  }\\n\\n  async calcAge2(n1: number, n2: number) {\\n    return n1 + n2\\n  }\\n\\n  protected async calcAge3(n1: number, n2: number) {\\n    return n1 + n2\\n  }\\n}\\n```\\n\\n## 快速生成特定的注释\\n\\n如我们想要给 Person添加一些备注说明，那么我们不能使用以下这种注释\\n\\n```typescript\\n// 这个单行注释不行\\n\\n/* 这个普通的多行注释也不行 */\\n```\\n\\n我们只能使用这种\\n\\n```\\n/**\\n*  这个是OK的\\n*/\\n```\\n\\n你可以在想要修饰的代码上方 输入 `/** + tab`  开快速生成\\n\\n![PixPin_2024-09-29_01-31-34](HarmonyNext%E5%A6%82%E4%BD%95%E4%BC%98%E9%9B%85%E7%9A%84%E7%BC%96%E5%86%99%E6%B3%A8%E9%87%8A.assets/PixPin_2024-09-29_01-31-34.gif)\\n\\n在带有参数的函数上方，它会自动添加参数的修饰符，包括返回值\\n\\n![PixPin_2024-09-29_01-33-28](HarmonyNext%E5%A6%82%E4%BD%95%E4%BC%98%E9%9B%85%E7%9A%84%E7%BC%96%E5%86%99%E6%B3%A8%E9%87%8A.assets/PixPin_2024-09-29_01-33-28.gif)\\n\\n## @param 和 @returns\\n\\n>  @param 修饰函数的形参\\n>\\n> @returns 修饰返回值\\n\\n\\n\\n![image-20240929013703645](HarmonyNext%E5%A6%82%E4%BD%95%E4%BC%98%E9%9B%85%E7%9A%84%E7%BC%96%E5%86%99%E6%B3%A8%E9%87%8A.assets/image-20240929013703645.png)\\n\\n\\n\\n## @async\\n\\n> @async 修饰 异步函数\\n\\n![image-20240929013924434](HarmonyNext%E5%A6%82%E4%BD%95%E4%BC%98%E9%9B%85%E7%9A%84%E7%BC%96%E5%86%99%E6%B3%A8%E9%87%8A.assets/image-20240929013924434.png)\\n\\n\\n\\n## @public\\n\\n> @public 公开\\n>\\n> @protected 受保护\\n>\\n> @private 私有 \\n\\n![image-20240929014127121](HarmonyNext%E5%A6%82%E4%BD%95%E4%BC%98%E9%9B%85%E7%9A%84%E7%BC%96%E5%86%99%E6%B3%A8%E9%87%8A.assets/image-20240929014127121.png)\\n\\n## @static\\n\\n![image-20240929014309520](HarmonyNext%E5%A6%82%E4%BD%95%E4%BC%98%E9%9B%85%E7%9A%84%E7%BC%96%E5%86%99%E6%B3%A8%E9%87%8A.assets/image-20240929014309520.png)\\n\\n# 其他的jsDoc规范的修饰符总览\\n\\n| 修饰符           | 含义                                   |\\n| ---------------- | -------------------------------------- |\\n| @abstract        | 表示一个抽象的成员，不能被直接实例化。 |\\n| @access          | 用于指定成员的访问级别。               |\\n| @alias           | 定义一个别名。                         |\\n| @async           | 表示一个异步函数。                     |\\n| @augments        | 指示一个类继承自另一个类。             |\\n| @author          | 作者信息。                             |\\n| @borrows         | 表示从另一个模块借用的函数或属性。     |\\n| @callback        | 表示一个回调函数。                     |\\n| @class           | 用于定义一个类。                       |\\n| @classdesc       | 类的描述。                             |\\n| @constant        | 表示一个常量。                         |\\n| @constructs      | 指示一个函数是构造函数。               |\\n| @copyright       | 版权信息。                             |\\n| @default         | 默认值。                               |\\n| @deprecated      | 表示已弃用的成员。                     |\\n| @description     | 描述信息。                             |\\n| @enum            | 定义一个枚举。                         |\\n| @event           | 表示一个事件。                         |\\n| @example         | 示例代码。                             |\\n| @exports         | 用于指定要导出的成员。                 |\\n| @external        | 表示外部模块的成员。                   |\\n| @file            | 文件信息。                             |\\n| @fires           | 表示触发的事件。                       |\\n| @function        | 定义一个函数。                         |\\n| @generator       | 表示一个生成器函数。                   |\\n| @global          | 表示全局成员。                         |\\n| @hideconstructor | 隐藏构造函数。                         |\\n| @ignore          | 表示忽略的部分。                       |\\n| @implements      | 表示实现的接口。                       |\\n| @inheritdoc      | 继承文档说明。                         |\\n| @inner           | 内部成员。                             |\\n| @instance        | 实例成员。                             |\\n| @interface       | 定义一个接口。                         |\\n| @kind            | 类型种类。                             |\\n| @lends           | 将属性借给另一个对象。                 |\\n| @license         | 许可证信息。                           |\\n| @listens         | 表示监听的事件。                       |\\n| @member          | 成员。                                 |\\n| @memberof        | 属于某个对象的成员。                   |\\n| @mixes           | 混合多个类的特性。                     |\\n| @mixin           | 定义一个混入。                         |\\n| @module          | 定义一个模块。                         |\\n| @name            | 名称。                                 |\\n| @namespace       | 命名空间。                             |\\n| @override        | 表示重写的成员。                       |\\n| @package         | 包信息。                               |\\n| @param           | 函数参数说明。                         |\\n| @private         | 私有成员。                             |\\n| @property        | 属性。                                 |\\n| @protected       | 受保护的成员。                         |\\n| @public          | 公共成员。                             |\\n| @readonly        | 只读属性。                             |\\n| @requires        | 表示依赖的模块。                       |\\n| @returns         | 函数返回值说明。                       |\\n| @see             | 参考信息。                             |\\n| @since           | 从某个版本开始。                       |\\n| @static          | 静态成员。                             |\\n| @summary         | 摘要信息。                             |\\n| @this            | 当前对象。                             |\\n| @throws          | 抛出的异常说明。                       |\\n| @todo            | 待办事项。                             |\\n| @tutorial        | 教程信息。                             |\\n| @type            | 类型说明。                             |\\n| @typedef         | 类型定义。                             |\\n| @variation       | 变化情况。                             |\\n| @version         | 版本信息。                             |\\n| @yields          | 生成的值说明。                         |\\n\\n\\n\\n# DevEco Studio 支持自定义修饰符\\n\\n**DevEco Studio** 是支持自定义修饰符的，比如\\n\\n![image-20240929010933164](HarmonyNext%E5%A6%82%E4%BD%95%E4%BC%98%E9%9B%85%E7%9A%84%E7%BC%96%E5%86%99%E6%B3%A8%E9%87%8A.assets/image-20240929010933164.png)\\n\\n虽然是可以随便自己设定，但是为了团队开发保持一直，还是建议按照一定的规范来编写。如 遵循 上述jsDoc的一些规范\\n\\n# DevEco Studio 快速生成说明文档\\n\\n**DevEco Studio NEXT Beta1(5.0.3.814)** \\n\\n- 当前支持对工程或目录下.ets/.ts/.js/.md格式文件生成ArkTSDoc文档。\\n- 文件中export的变量、方法、接口、类等将生成相应的ArkTSDoc文档，未export的对象不支持生成。\\n- 若选择对工程/目录整体导出ArkTSDoc文档，生成后的ArkTSDoc文档目录和原目录结构一致。\\n\\n\\n\\n![image-20240929014948209](HarmonyNext%E5%A6%82%E4%BD%95%E4%BC%98%E9%9B%85%E7%9A%84%E7%BC%96%E5%86%99%E6%B3%A8%E9%87%8A.assets/image-20240929014948209.png)\\n\\n\\n\\n---\\n\\n![image-20240929015033130](HarmonyNext%E5%A6%82%E4%BD%95%E4%BC%98%E9%9B%85%E7%9A%84%E7%BC%96%E5%86%99%E6%B3%A8%E9%87%8A.assets/image-20240929015033130.png)\\n\\n\\n\\n\\n\\n# 参考链接\\n\\n1. [@use JSDoc](https://jsdoc.app/)\\n2. [生成ArkTSDoc文档](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides-V5/ide-arktsdoc-V5)"}'),D={name:"鸿蒙开发技巧/HarmonyOS Next 如何优雅的编写注释/HarmonyNext如何优雅的编写注释.md"};function B(F,s,C,_,x,v){return a(),t("div",null,[...s[0]||(s[0]=[i("",64)])])}const P=n(D,[["render",B]]);export{q as __pageData,P as default};
